// auditLogAllColumns is the column list for full-entity reads, sorted for determinism.
var auditLogAllColumns = []string{"created_at", "id", "message"}

// scanAuditLogs scans rows into AuditLog entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanAuditLogs(rows database.Rows, columns []string) ([]*AuditLog, error) {
	var result []*AuditLog
	for rows.Next() {
		a := &AuditLog{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "id":
				targets[idx] = &a.ID
			case "message":
				targets[idx] = &a.Message
			case "created_at":
				targets[idx] = &a.CreatedAt
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan audit_log: %w", err)
		}

		result = append(result, a)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate audit_log rows: %w", err)
	}
	return result, nil
}

